drc03=function(){const e=[];['c','s','f','t'].forEach(k=>{if(!$('d3_'+k).value)e.push('All fields are mandatory')});const c=cashBal(),m={};let tot=0;const need=[];
H.forEach(h=>{m[h]={};MIN.forEach(k=>{const el=$('d3_'+h+'_'+k),v=Math.max(0,el?+el.value||0:0);m[h][k]=v;tot+=v;if(v>c[h+'_'+k]+0.001)need.push(HN[h]+' '+MINL[k]+': short by ₹'+f(v-c[h+'_'+k]))})});
if(!(tot>0))e.push('Enter the amount being paid');if(need.length)e.push('Insufficient cash ledger balance under the same minor head - create a challan first. '+need.join('; '));if(e.length){$('d3_e').innerHTML=[...new Set(e)].join('<br>');return}if(!evc('DRC-03'))return;
const arn=m6arn('AD'),deb={};H.forEach(h=>MIN.forEach(k=>deb[h+'_'+k]=-m[h][k]));addCash('DRC-03 voluntary payment - ARN '+arn,deb);const cs=$('d3_c').value,sec=$('d3_s').value;
addLiab2({ref:arn,src:'DRC-03',desc:'Liability created - Form GST DRC-03 ('+cs+', '+sec+')',type:'Dr',m});addLiab2({ref:arn,src:'DRC-03',desc:'Paid - Form GST DRC-03 ('+cs+') - debited from Electronic Cash Ledger',type:'Cr',m});
const l=get('drc03',[]);l.unshift({arn,d:today(),c:cs,s:sec,amt:tot});put('drc03',l);addApp({kind:'pay',type:'Intimation of voluntary payment (DRC-03) - '+cs,arn,date:today(),status:'Filed - debited from cash ledger'});m6done('DRC-03 filed. ARN '+arn+'. ₹'+f(tot)+' debited from the electronic cash ledger.','Intimation of Voluntary Payment (DRC-03)')};
(function(){const _lr=V['Electronic Liability Register'];V['Electronic Liability Register']=()=>{seed13b();if(window._q7.lpart!==2){let h=_lr();return h.replace(/<a href="#" onclick="show\('Intimation of Voluntary Payment \(DRC-03\)'\);return false">Part-II/,`<a href="#" id="lr_p2" onclick="window._q7.lpart=2;show('Electronic Liability Register');return false">Part-II`).replace('<a class="on">Part-I','<a class="on" id="lr_p1">Part-I')}
const q=window._q7.liab2||{act:'all'},heads=q.act==='all'?H:[q.act],ll=m7l2(q),run={};MIN.forEach(k=>run[k]=0);
const rows=ll.map((e,i)=>{const a=m7sumM(e.m,heads),s=e.type==='Cr'?-1:1;MIN.forEach(k=>run[k]+=s*a[k]);return `<tr><td>${i+1}</td><td>${dmy(e.d)}</td><td>${esc(e.ref)}</td><td>${e.type==='Cr'?'Electronic Cash Ledger':'-'}</td><td>${esc(e.desc)}</td><td>${e.type==='Cr'?'Credit (CR) (Paid)':'Debit (DR) (Payable)'}</td>${MIN.map(k=>`<td class="n">${f(a[k])}</td>`).join('')}<td class="n">${f(MIN.reduce((t,k)=>t+a[k],0))}</td>${MIN.map(k=>`<td class="n">${f(Math.max(0,run[k]))}</td>`).join('')}<td class="n">${f(Math.max(0,MIN.reduce((t,k)=>t+run[k],0)))}</td></tr>`}).join('');
const dem=[...new Set(ll.filter(e=>e.src==='DRC-07').map(e=>e.ref))].map(r=>{const b=liab2Bal(r),o=H.reduce((s,h)=>s+MIN.reduce((t,k)=>t+Math.max(0,b[h][k]),0),0);return [r,o]});
return card('Electronic Liability Register',`<div class="tabs"><a href="#" id="lr_p1" onclick="window._q7.lpart=1;show('Electronic Liability Register');return false">Part-I: Return related liabilities</a><a class="on" id="lr_p2">Part-II: Other than return related liabilities</a></div>
<div class="row"><div><label>From date</label><input type="date" id="lr2_f" value="${q.f||''}"></div><div><label>To date</label><input type="date" id="lr2_t" value="${q.t||''}"></div><div><label>Tax period</label><select id="lr2_p"><option value="">All</option>${[...new Set(get('liab2',[]).map(e=>e.p).filter(Boolean))].sort().reverse().map(p=>`<option value="${p}" ${q.p===p?'selected':''}>${periodLabel(p)}</option>`).join('')}</select></div>${actSel('lr2_act',q.act)}<div style="flex:0 0 auto"><button class="btn s" id="lr2_go" onclick="const f=$('lr2_f').value,t=$('lr2_t').value;if(f&&t&&f>t){$('lr2_e').textContent='From date cannot be after To date';return}window._q7.liab2={act:$('lr2_act').value,f,t,p:$('lr2_p').value};show('Electronic Liability Register')">SEARCH</button></div></div><p class="err" id="lr2_e"></p>
<div class="tscroll"><table id="liab2T" class="ledT"><tr><th rowspan=2>Sr. No.</th><th rowspan=2>Date (dd/mm/yyyy)</th><th rowspan=2>Reference No. (Demand ID / ARN)</th><th rowspan=2>Ledger used for discharging liability</th><th rowspan=2>Description</th><th rowspan=2>Type of Transaction [Debit (DR) (Payable)] / [Credit (CR) (Paid)]</th><th colspan=6>Amount debited/credited (₹) - ${ACTS.find(a=>a[0]===q.act)[1]}</th><th colspan=6>Balance (Payable) (₹)</th></tr><tr>${[...MIN,'t'].map(m=>`<th>${MINL[m]||'Total'}</th>`).join('').repeat(2)}</tr>${rows||'<tr><td colspan=18>No records found</td></tr>'}</table></div>
<h4>Outstanding demands</h4><table id="demT"><tr><th>Demand ID</th><th>Outstanding (₹)</th><th>Action</th></tr>${dem.map(([r,o])=>`<tr><td>${r}</td><td class="n">${f(o)}</td><td>${o>0?`<button class="btn s" onclick="payDemand('${r}')">PAY (DRC-03)</button>`:'Paid'}</td></tr>`).join('')||'<tr><td colspan=3>No outstanding demand</td></tr>'}</table>
<div class="note">Part-II shows liabilities other than return related ones: demands created by orders (e.g. DRC-07) and voluntary payments intimated in Form GST DRC-03, with Tax, Interest, Penalty, Fee and Others in separate columns. <a href="#" onclick="show('Intimation of Voluntary Payment (DRC-03)');return false">File DRC-03</a> · <a href="#" id="lr2_new" onclick="show('Create Demand (DRC-07) - Officer Simulation');return false">Create demand (officer simulation)</a></div>`,'payments')}})();
/* --- Challan History: layout as per official user manual (tutorial.gst.gov.in, Track Payment Status (Post Login), image50) --- */
function m7reason(c){const r=String(c.reason||'');return /quarterly/i.test(r)?(/35/.test(r)||c.ctype==='35'?'MPQR (35% Challan)':'MPQR (Self assessed)'):'AOP'}
function m7time(c){if(c.tm)return c.tm;let h=0;for(const ch of String(c.cpin))h=(h*31+ch.charCodeAt(0))%86400;return [h/3600|0,(h/60|0)%60,h%60].map(x=>String(x).padStart(2,'0')).join(':')}
function m7st(c){if(/^Awaiting/.test(c.st||''))return c.st.toUpperCase()+'*';return c.st==='Paid'?'PAID':c.st==='Cancelled'?'CANCELLED':(c.exp&&c.exp<today()?'EXPIRED':'NOT PAID')}
V['Challan History']=()=>{const q=window._q7.ch||{},all=get('ch',[]).slice().sort((a,b)=>(b.d+m7time(b)).localeCompare(a.d+m7time(a)));let l=all;if(q.cpin)l=all.filter(c=>c.cpin===q.cpin);else if(q.f)l=all.filter(c=>c.d>=q.f&&c.d<=q.t);const pg=q.pg||1,pages=Math.max(1,Math.ceil(l.length/10)),sh=l.slice((pg-1)*10,pg*10),byC=q.mode!=='date';
return card('Challan History',`<div class="tabs"><a href="#" onclick="show('Create Challan');return false">Create Challan</a><a href="#" onclick="show('Saved Challans');return false">Saved Challan</a><a class="on">Challan History</a></div>
<div class="inline" id="chRadio"><label><input type="radio" name="chs" id="chs_c" ${byC?'checked':''} onclick="window._q7.ch={...(window._q7.ch||{}),mode:'cpin'};$('chC').classList.remove('hide');$('chD').classList.add('hide')"> Search By CPIN</label><label><input type="radio" name="chs" id="chs_d" ${byC?'':'checked'} onclick="window._q7.ch={...(window._q7.ch||{}),mode:'date'};$('chD').classList.remove('hide');$('chC').classList.add('hide')"> Search By Date</label></div>
<div class="msg" id="chMsg">Kindly search the CPIN to retrieve its latest payment status from bank.</div>
<div id="chD" class="${byC?'hide':''}">${m7range('ch',q.f||m7def()[0],q.t||today())}</div><div id="chC" class="row ${byC?'':'hide'}"><div><label>CPIN <span class="req">*</span></label><input id="ch_cp" placeholder="Enter CPIN" value="${q.cpin||''}" maxlength="14"></div><div style="flex:0 0 auto"><button class="btn s" id="ch_cpgo" onclick="window._q7.ch={cpin:$('ch_cp').value.trim(),mode:'cpin'};show('Challan History')">SEARCH</button></div></div>
<table id="chH"><tr><th>CPIN</th><th>Created On</th><th>Amount (₹)</th><th>Mode</th><th>Challan Reason</th><th>Expiry Date</th><th>Deposit Date</th><th>Deposit Status</th></tr>${sh.map(c=>`<tr><td><a href="#" onclick="$('main').innerHTML=receipt(get('ch',[]).find(x=>x.cpin==='${c.cpin}'));return false">${c.cpin}</a></td><td>${dmy(c.d)}<br>${m7time(c)}</td><td class="n">${Number(c.total||0).toLocaleString('en-IN')}</td><td>${c.mode==='Over the Counter'?'Over The Counter':/^E-Payment/.test(c.mode)?'E-Payment':c.mode}</td><td>${m7reason(c)}</td><td>${dmy(c.exp)}</td><td>${c.st==='Paid'?dmy(c.paidOn||c.d):'-'}</td><td>${m7st(c)}${m7st(c)==='NOT PAID'&&c.mode==='Over the Counter'?`<br><a href="#" class="chx" onclick="chCancel('${c.cpin}');return false">Cancel</a>`:''}</td></tr>`).join('')||'<tr><td colspan=8>No records found</td></tr>'}</table>
<div class="pager" id="chPg">${pages>1?Array.from({length:pages},(_,i)=>`<a href="#" class="${i+1===pg?'on':''}" onclick="window._q7.ch={...(window._q7.ch||{}),pg:${i+1}};show('Challan History');return false">${i+1}</a>`).join(' '):''}</div>
<button class="btn" id="ch_csv" onclick="m7csv('challan_history',[['CPIN','Created On','Amount (₹)','Mode','Challan Reason','Expiry Date','Deposit Date','Deposit Status'],...get('ch',[]).map(c=>[c.cpin,dmy(c.d)+' '+m7time(c),c.total,c.mode,m7reason(c),dmy(c.exp),c.st==='Paid'?dmy(c.paidOn||c.d):'-',m7st(c)])])">DOWNLOAD AS CSV</button>
<div class="note">ⓘ If amount is deducted from bank account and not reflected in electronic cash ledger, you may raise grievance under <a href="#" onclick="show('Grievance against Payment (GST PMT-07)');return false">"Services&gt;Payments&gt;Grievance against payment(GST PMT-07)"</a><br>ⓘ *Awaiting Bank Confirmation: For e-payment mode of payment, if the maker has made a transaction and checker approval is not communicated by bank to GST System.<br>ⓘ *Awaiting Bank Clearance: For OTC mode of payment, if bank has acknowledged the challan but remittance confirmation is not communicated by bank to GST System.<br>ⓘ Challan Reason Abbreviations: ● MPQR (35% Challan) - Monthly payment for quarterly return (35% challan) ● MPQR (Self assessed) - Monthly payment for quarterly return (Self assessed) ● AOP - Any other payment.</div>`,'payments')};
