function m7l2(q){q=q||{};return get('liab2',[]).filter(e=>(!q.f||e.d>=q.f)&&(!q.t||e.d<=q.t)&&(!q.p||e.p===q.p))}
/* officer simulation: create a DRC-07 demand that posts to PMT-01 Part II */
V['Create Demand (DRC-07) - Officer Simulation']=()=>{const fy=fyOf(S.p);return card('Create Demand (DRC-07) - Officer Simulation',`<div class="note">Practice only: plays the role of the proper officer issuing a summary of order in Form GST DRC-07. The demand is posted to the Electronic Liability Register Part-II of this GSTIN.</div>
<div class="row"><div><label>Order type <span class="req">*</span></label><select id="dm_s"><option value="">Select</option><option>Order u/s 73</option><option>Order u/s 74</option><option>Order u/s 122 (penalty)</option><option>Order u/s 125 (general penalty)</option><option>Others</option></select></div><div><label>Order No. <span class="req">*</span></label><input id="dm_no" placeholder="e.g. ORD/PR/01"></div><div><label>Tax period <span class="req">*</span></label><input type="month" id="dm_p" value="${S.p}"></div></div>
<table id="dmT"><tr><th>Head</th>${MIN.map(k=>`<th>${MINL[k]} (₹)</th>`).join('')}</tr>${H.map(h=>`<tr><td>${HN[h]}</td>${MIN.map(k=>`<td><input type="number" min="0" id="dm_${h}_${k}" value="0"></td>`).join('')}</tr>`).join('')}</table>
<p class="err" id="dm_e"></p><button class="btn s" id="dm_go" onclick="m7demand()">ISSUE DEMAND (DRC-07)</button> <button class="btn" onclick="window._q7.lpart=2;show('Electronic Liability Register')">VIEW PART-II</button>`,'payments')};
function m7demand(){const s=$('dm_s').value,no=$('dm_no').value.trim(),p=$('dm_p').value,e=[];if(!s||!no||!p)e.push('All fields are mandatory');const m=m7z5();let t=0;H.forEach(h=>MIN.forEach(k=>{const v=Math.max(0,+$('dm_'+h+'_'+k).value||0);m[h][k]=v;t+=v}));if(!(t>0))e.push('Enter the demand amount');if(e.length){$('dm_e').innerHTML=[...new Set(e)].join('<br>');return}
const id='ZD'+G.slice(0,2)+today().replace(/-/g,'').slice(2,6)+String(Math.floor(Math.random()*1e7)).padStart(7,'0');addLiab2({ref:id,p,src:'DRC-07',desc:'Demand created - '+s+' (Order No. '+no+', summary in Form GST DRC-07)',type:'Dr',m});
addApp({kind:'pay',type:'Demand (DRC-07) - '+s,arn:id,date:today(),status:'Demand outstanding'});alert('Demand '+id+' of ₹'+f(t)+' posted to Electronic Liability Register Part-II.');window._q7.lpart=2;window._q7.liab2={act:'all'};show('Electronic Liability Register')}
/* challan statuses: OTC / NEFT stay "Awaiting Bank Clearance"; corporate (maker-checker) e-payment stays "Awaiting Bank Confirmation" */
(function(){const _pn=payNow;payNow=function(cp){const l=get('ch',[]),c=l.find(x=>x.cpin===cp);if(!c)return;if(c.st==='Not Paid'&&!/E-Payment/.test(c.mode)){if(c.exp<today())return alert('Challan expired. Create a new challan.');c.st='Awaiting Bank Clearance';c.ackOn=today();put('ch',l);alert('Bank has acknowledged the challan. Status: Awaiting Bank Clearance (remittance confirmation from bank not yet received by GST System).');$('main').innerHTML=receipt(c);return}
if(/^Awaiting/.test(c.st)){const prev=c.st;c.st='Not Paid';put('ch',l);const exp=c.exp;c.exp='2999-12-31';put('ch',l);_pn(cp);const l2=get('ch',[]),c2=l2.find(x=>x.cpin===cp);c2.exp=exp;if(c2.st!=='Paid')c2.st=prev;put('ch',l2);if($('main')&&c2)$('main').innerHTML=receipt(c2);return}return _pn(cp)};
window.mcPay=function(cp){const l=get('ch',[]),c=l.find(x=>x.cpin===cp);if(c.exp<today())return alert('Challan expired. Create a new challan.');if(!confirm('[Simulated corporate net banking] Maker submits the payment; checker approval pending. Proceed?'))return;c.st='Awaiting Bank Confirmation';c.ackOn=today();put('ch',l);alert('Status: Awaiting Bank Confirmation (maker has made the transaction; checker approval not yet communicated by bank).');$('main').innerHTML=receipt(c)};
const _r=receipt;receipt=function(c){let h=_r(c);if(/^Awaiting/.test(c.st||'')){h=h.replace('Simulate bank confirmation','SIMULATE BANK REMITTANCE CONFIRMATION').replace('>MAKE PAYMENT<','>SIMULATE CHECKER APPROVAL (BANK CONFIRMATION)<').replace(/(class="st )NotPaid/,'$1NotPaid" id="rcSt')}
else if(c.st==='Not Paid'&&/E-Payment/.test(c.mode))h=h.replace('>MAKE PAYMENT</button>',`>MAKE PAYMENT</button> <button class="btn" id="mc_${c.cpin}" onclick="mcPay('${c.cpin}')">PAY VIA CORPORATE NET BANKING (MAKER-CHECKER)</button>`);return h}})();
(function(){const g=MENU.find(x=>x[0]==='Ledgers');if(g&&!g[1].includes('Create Demand (DRC-07) - Officer Simulation')){g[1].push('Create Demand (DRC-07) - Officer Simulation');if($('menu'))$('menu').innerHTML=MENU.map(([gg,items])=>items?`<h5>${gg}</h5>`+items.map(i=>`<button onclick="show('${i}')">${i==='Negative Liability Statement'&&!COMP?'Negative Liability Statement - Regular Taxpayers':i}</button>`).join(''):`<button onclick="show('${gg}')">${gg}</button>`).join('')}})();
